import type { IconifyJSON } from '@iconify/types';
import { addCollection } from '@iconify/vue';
import heroicons from './iconSubsets/heroicons.json';
import lucide from './iconSubsets/lucide.json';

// Offline Iconify registration (self-hosted — no runtime calls to the
// Iconify API, per the no-third-party-trackers stance). Only the strict
// icon subsets generated by `npm run icons:build` (scripts/
// build-icon-subsets.mjs) from the icon manifests ship to the browser —
// the full heroicons/lucide packs (~1.2 MB raw) would bloat the app
// chunk. devicon registers statically in the TechSkills page (5.2 —
// race-free at page load, without bloating the app bundle); simple-icons
// registers in the feature steps that consume them (7.2 / 9.1).
addCollection(heroicons as IconifyJSON);

// The lucide subset covers only the two icons the TextEditor's
// subscript/superscript buttons need (heroicons has no sub/superscript
// glyphs; B231) — the generated subset keeps the bundle flat while
// staying offline.
addCollection(lucide as IconifyJSON);
